<?php

/**
 * Hand-written code. NOT generated by Speakeasy. Safe from regeneration.
 *
 * @see docs/REGENERATION.md
 */

declare(strict_types=1);

namespace Factuarea\Sdk\Custom\Response;

use Factuarea\Sdk\Models\Errors\APIException;
use Psr\Http\Message\ResponseInterface;

/**
 * Status, `ETag`, `Retry-After` and JSON body of a response, whichever way the
 * generated operation surfaced it: as its typed response (`->rawResponse`) or as
 * an {@see APIException} (a status the pinned spec does not declare, such as a
 * 202 or a 503, reaches the caller that way and the exception keeps the raw
 * response and body).
 */
final class ResponseMeta
{
    public function __construct(
        public readonly int $statusCode,
        public readonly ?string $etag,
        /** Seconds to wait, from `Retry-After` (delta-seconds or HTTP-date); null when absent or unparsable. */
        public readonly ?int $retryAfter,
        public readonly string $body,
    ) {
    }

    public static function fromResponse(ResponseInterface $response): self
    {
        $etag = $response->getHeaderLine('ETag');
        $body = (string) $response->getBody();
        if ($response->getBody()->isSeekable()) {
            $response->getBody()->rewind();
        }

        return new self(
            $response->getStatusCode(),
            $etag === '' ? null : $etag,
            self::retryAfterSeconds($response->getHeaderLine('Retry-After')),
            $body,
        );
    }

    public static function fromException(APIException $exception): self
    {
        if ($exception->rawResponse === null) {
            return new self($exception->statusCode, null, null, $exception->body);
        }

        $meta = self::fromResponse($exception->rawResponse);

        // The generated code already drained the stream into `$exception->body`.
        return new self($meta->statusCode, $meta->etag, $meta->retryAfter, $meta->body !== '' ? $meta->body : $exception->body);
    }

    /**
     * Decoded JSON body, or null when it is empty or not valid JSON.
     */
    public function json(): mixed
    {
        if ($this->body === '') {
            return null;
        }

        try {
            return json_decode($this->body, true, 512, JSON_THROW_ON_ERROR);
        } catch (\JsonException) {
            return null;
        }
    }

    private static function retryAfterSeconds(string $value): ?int
    {
        $value = trim($value);
        if ($value === '') {
            return null;
        }
        if (ctype_digit($value)) {
            return (int) $value;
        }

        $timestamp = strtotime($value);

        return $timestamp === false ? null : max(0, $timestamp - time());
    }
}
